/**
 * Load a maximal example of {@link types.StructuralFirst} from
 * the test data directory.
 */
export function loadMaximalStructuralFirst(
): OurTypes.StructuralFirst {
  const aPath = path.join(
    TestCommon.TEST_DATA_DIR,
    "Json",
    "Expected",
    "StructuralFirst",
    "maximal.json"
  );

  const jsonable = TestCommon.readJsonFromFileSync(aPath);

  const instanceOrError = OurJsonization.structuralFirstFromJsonable(
    jsonable
  );
  expect(instanceOrError.error).toBeNull();
  const instance = instanceOrError.mustValue();

  const casted = OurTypes.asStructuralFirst(instance);
  if (casted === null) {
    throw new Error(
      `Expected instance of StructuralFirst in ${aPath}, ` +
      `but got: ${typeof instance}`
    );
  }
  return casted;
}

